export const systemsModule2Path = "/study/systems/module-2";
export const systemsModule2Sources = {
  review: { title: "AMEM 10004 Review Test 2", slides: 38 },
  components: { title: "Hydraulic Components (2024)", pages: 113 },
};
export const systemsModule2Easy = [], systemsModule2Medium = [], systemsModule2Hard = [];
export const systemsModule2NoteSections = [];
const sections = new Map();
const titles = {
  selectors: "Selector valves · open/closed centre, poppet, spool and rotary",
  valves: "Check valves, metering valves and accumulators",
  switches: "Pressure, thermal, position and limit switches",
  fuses: "Hydraulic fuses · pressure versus measured volume",
  sequence: "Sequence and priority valves",
  filters: "Filters · indicators, bypass and each element type",
  seals: "Gaskets, packing, O-rings and backup rings",
  identification: "Seal identification · cure quarters and each colour code",
  installation: "Seal installation, wipers and crush washers",
  pneumatics: "Pneumatic storage, emergency systems and shuttle valves",
  pumps: "Compressors, vane pumps and hydraulic pump designs",
};

function add(id, topic, prompt, options, why, pages, recall, reviewSlides = [], extra = {}) {
  const source = { deck: "components", pages, reviewSlides };
  const explanation = `${why} (Hydraulic Components (2024), PDF pages / slides ${pages.join(", ")}${reviewSlides.length ? `; AMEM 10004 Review Test 2, slides ${reviewSlides.join(", ")}` : ""}.)`;
  const question = { id: `systems2-medium-${id}`, learningTarget: id, topic, prompt, options, correctIndex: 0, explanation, source, ...extra };
  systemsModule2Medium.push(question);
  if (reviewSlides.length) systemsModule2Easy.push({ ...question, id: `systems2-easy-${id}`, options: [...options] });
  if (recall) systemsModule2Hard.push({ id: `systems2-hard-${id}`, learningTarget: id, topic, prompt: recall[0], answer: recall[1], acceptedAnswers: [recall[1], ...(recall[2] ?? [])], explanation, source });
  if (!sections.has(topic)) sections.set(topic, []);
  sections.get(topic).push([extra.term ?? options[0], explanation]);
}

add("selector-role", "selectors", "Which valve directs hydraulic fluid to and from a selected actuator?", ["Selector valve", "Check valve", "Pressure fuse", "Shuttle valve"], "A selector routes pressure and return flow for the selected component. A check valve mainly controls permitted flow direction; a fuse isolates a failed branch rather than selecting actuator motion.", [3], ["A _____ valve directs pressure and return flow to the selected component.", "selector"], [2, 3]);
add("pilot-control", "selectors", "Who can directly command the operator-controlled selector in the lesson?", ["The pilot", "Only the filter's bypass spring", "Only the accumulator gas charge", "Only the fluid-temperature switch"], "The lesson identifies operator control by the pilot separately from automated control. The command selects a flow path; filter condition and stored pressure are different system functions.", [3], ["In the lesson, the operator commanding a selector can be the _____.", "pilot"]);
add("automatic-control", "selectors", "Which example can command a selector automatically?", ["Autopilot", "A passive particle filter", "A fixed backup ring", "A reservoir filler cap"], "The deck lists the autopilot as an automated control source. A selector can therefore receive a system command as well as a pilot command; passive sealing and filtering parts do not perform this command role.", [3], ["The automated selector-control example is the _____.", "autopilot"]);
add("open-neutral", "selectors", "In the illustrated open-centre selector, where does fluid flow with the selector neutral?", ["Through the valve to return", "Into a blocked pressure passage only", "Continuously into both actuator chambers", "Out through an external leakage drain"], "An open-centre selector leaves a through-flow route to the return port in neutral. Selecting extend or retract changes that route to supply the actuator, unlike the blocked neutral pressure path in the closed-centre example.", [6, 8, 12], ["In the open-centre neutral example, fluid passes through the valve to _____.", "return", ["reservoir"]], [2, 3]);
add("closed-neutral", "selectors", "What happens to pressure flow through the lesson's closed-centre selector in neutral?", ["It is blocked through the selector", "It passes freely through to return", "It is sent to both actuator ends", "It must leak outside the valve body"], "The closed-centre neutral arrangement blocks flow through the selector. This describes the selector's neutral porting, not a claim that every part of the complete hydraulic system stops operating.", [9, 16, 17], ["The closed-centre selector's neutral pressure path is _____.", "blocked", ["closed"]], [2]);
add("rotary-design", "selectors", "Which selector design changes the flow path by turning an internal cylinder?", ["Rotary", "Spool", "Poppet", "Flapper check"], "The rotary design turns a cylinder to align different pressure and return passages. The spool instead slides, while the poppet design lifts valves from their seats.", [4, 19, 20], ["A selector with a turning internal cylinder is a _____ design.", "rotary"], [2]);
add("poppet-design", "selectors", "Which selector design directs flow by lifting valves from their seats?", ["Poppet", "Rotary", "Spool", "Swing check"], "Poppets lift from their seats to open a passage. The lesson compares their T-shaped form with engine intake/exhaust valves; this differs from a sliding spool or rotating cylinder.", [4, 5], ["A selector that lifts seated T-shaped valves is a _____ design.", "poppet"], [2]);
add("spool-design", "selectors", "Which selector design directs flow by sliding a shaft or piston?", ["Spool", "Rotary", "Poppet", "Ball check"], "A spool slides within the valve, covering or uncovering ports. Short spool movements can change the available flow opening, which is why this design can meter flow.", [4, 11], ["A sliding shaft or piston identifies a _____ valve.", "spool"], [2]);
add("poppet-cam", "selectors", "What opens the poppets in the mechanical design described in the deck?", ["A cam", "A filter element", "A backup ring", "A reservoir baffle"], "The cam mechanically lifts the poppets from their seats. Hydraulic pressure or a spring closes them in the described design; opening and closing forces should not be confused.", [5], ["The described poppets are mechanically opened by a _____.", "cam"]);
add("poppet-closing", "selectors", "What closes a poppet in the lesson's example?", ["Hydraulic pressure or a spring", "Only the pilot's direct hand force on the poppet", "The filter cleaning blade", "The reservoir's fluid-level pointer"], "The lesson specifies hydraulic pressure or spring force for closing. The cam supplies the opening movement, so the actuator that lifts the poppet is not the same as its closing force.", [5], ["Alongside hydraulic pressure, a _____ can close the described poppet.", "spring"]);
add("spool-metering", "selectors", "How can a spool valve meter hydraulic flow?", ["By varying how much of a port is uncovered", "By changing the chemical type of the fluid", "By raising the reservoir's gas temperature only", "By replacing the return line with a filter"], "Moving the spool changes the area of the flow opening. A partially uncovered port provides a different restriction from a fully open port, allowing control of flow rate.", [11], ["A spool meters flow by covering or uncovering the flow _____.", "port", ["opening"]]);
add("servo-position", "selectors", "What does the lesson say the servo spool arrangement does at the desired travel?", ["Closes the valve automatically", "Removes the filter element", "Vents all fluid overboard", "Replaces the actuator with a reservoir"], "The servo arrangement closes its control valve when the desired travel is reached. This connects valve position with commanded movement instead of maintaining actuator flow indefinitely.", [11, 18], ["At the desired travel, the servo arrangement closes the valve _____.", "automatically"]);
add("rotary-reversal", "selectors", "In the rotary-selector example, what reverses actuator motion?", ["Routing pressure to the opposite actuator port", "Filtering the same flow twice", "Replacing a gasket with a wiper", "Opening the reservoir filler cap"], "Turning the rotary control changes which actuator port receives pressure and which returns fluid. Reversing these flow connections reverses the commanded actuator movement.", [19, 20], ["A rotary selector reverses motion by supplying the _____ actuator port.", "opposite"]);
add("actuator-return", "selectors", "With extend or retract selected in the open-centre example, how does displaced actuator fluid return?", ["Through the selector into the return line", "Through the pressure-fuse case to the atmosphere", "Through the accumulator gas chamber", "Through the electrical switch contacts"], "The selector provides a pressure route to one actuator chamber and a return route from the other. Without the displaced-fluid return path, the intended actuator movement cannot proceed as shown.", [7, 8], ["Displaced actuator fluid passes through the selector into the _____ line.", "return"], [3]);

add("check-direction", "valves", "What is the normal purpose of an ordinary check valve?", ["Permit flow in one direction", "Select the order of several actuators", "Store fluid under pressure", "Measure the filter's contamination"], "A check valve permits the intended direction and blocks reverse flow. An orifice check is a special arrangement that also provides a restricted reverse route; it should not be confused with an ordinary one-way check.", [21, 22], ["An ordinary check valve is a _____-way valve.", "one", ["1"]], [4]);
add("inline-check", "valves", "What identifies an inline check valve in the review?", ["A separate component between other components", "A check incorporated inside another component", "A valve that must allow equal flow both ways", "A device with no permitted flow direction"], "An inline check is a standalone unit installed in the line between components. An integral check instead forms part of another component, such as a pump or actuator.", [21], ["A standalone check installed between components is an _____ check.", "inline", ["in-line"]], [4]);
add("integral-check", "valves", "What identifies an integral check valve?", ["It is incorporated into another component", "It is always a separate line-mounted unit", "It is a filter bypass indicator", "It is a manually adjusted seal support"], "An integral check is built into another component, for example a pump or flight-control actuator. Integral describes its installation relationship, not a different permission for reverse flow.", [21], ["A check built into a pump or actuator is an _____ check.", "integral"], [4]);
add("check-arrow", "valves", "What does the arrow on the review's inline check valve indicate?", ["Permitted flow direction", "The highest point for mounting", "The direction of the gas precharge", "The position of the electrical connector"], "The arrow identifies the direction in which the check is intended to pass fluid. It is a flow mark, not a mounting-up arrow or an electrical polarity mark.", [21], ["The arrow on the check valve marks permitted flow _____.", "direction"], [4]);
add("ball-check", "valves", "Which check-valve design uses a spring-loaded ball as its closing member?", ["Ball type", "Cone type", "Swing type", "Rotary selector"], "The ball is pressed against its seat by spring force in the illustrated design. The shape of the closing member distinguishes it from the cone and hinged flapper designs.", [22, 25], ["A spring-loaded spherical closing member identifies a _____ check.", "ball"]);
add("cone-check", "valves", "Which check-valve design uses a cone-shaped plunger?", ["Cone type", "Ball type", "Swing type", "Spool selector"], "The cone-shaped plunger closes against the seat with spring assistance. A cone, ball and flapper can all perform a checking function but use different closing members.", [22, 25], ["A check with a tapered cone-shaped plunger is a _____ type.", "cone"]);
add("swing-check", "valves", "Which check-valve design uses a hinged flapper?", ["Swing type", "Ball type", "Cone type", "Sliding-spool type"], "The swing check opens and closes using a flapper rather than a ball or cone moving onto a seat. The lesson describes spring assistance in its illustrated example.", [22, 25], ["A hinged flapper identifies a _____ check valve.", "swing"]);
add("orifice-check", "valves", "How does an orifice check valve differ from an ordinary one-way check?", ["It permits full flow one way and restricted flow in reverse", "It blocks all flow in both directions", "It provides equal unrestricted flow in both directions", "It stores pressure in a separate gas chamber"], "The orifice provides a controlled reverse-flow path while the check allows fuller flow in the other direction. This creates unequal flow resistance instead of simply blocking all reverse flow.", [23, 24], ["An _____ check gives full flow one way and restricted flow in reverse.", "orifice"]);
add("orifice-gear", "valves", "Why does the lesson show orifice checks in landing-gear circuits?", ["To restrict flow so gear movement is not too rapid", "To remove particles from the fluid", "To provide the gear's electrical position signal", "To replace the hydraulic reservoir"], "Restricting flow controls the rate of actuator movement. The landing-gear example uses this to prevent excessively rapid extension, rather than using the orifice check as a filter or storage device.", [24], ["The gear example uses an orifice check to prevent extension that is too _____.", "rapid", ["fast"]]);
add("metering-role", "valves", "Which valve directly controls the rate of fluid flow in the brake-control example?", ["Metering valve", "Ordinary check valve", "Hydraulic fuse", "Shuttle valve"], "The metering valve regulates flow rate. This distinguishes controlling the amount of flow from choosing between pressure sources or isolating a failed line.", [26], ["A _____ valve controls fluid flow rate in the brake-control example.", "metering"]);
add("accumulator-role", "valves", "What does a hydraulic accumulator store?", ["Fluid under pressure", "Only drained contaminants", "Only an electrical position signal", "Unpressurized cleaning solvent"], "An accumulator stores hydraulic fluid under pressure with a separate gas space. Stored pressure can remain after a pump stops, so pump shutdown alone does not establish that the accumulator is discharged.", [27, 28, 29], ["The component storing hydraulic fluid under pressure is an _____.", "accumulator"]);
add("accumulator-chambers", "valves", "What separates the two spaces identified in the accumulator lesson?", ["Gas and hydraulic fluid occupy separate chambers", "Both spaces contain only return-line debris", "Both spaces are electrical switch compartments", "One chamber is a filter and the other a wiper"], "The lesson calls these air and fluid chambers and shows a separating element between them. The gas side and hydraulic-fluid side have different roles; this does not authorize an arbitrary gas for charging any aircraft accumulator.", [27, 28], ["An accumulator's separating element keeps its _____ chamber apart from the fluid chamber.", "gas", ["air"]]);
for (const [id, name, clue] of [["diaphragm", "Diaphragm", "a flexible membrane"], ["bladder", "Bladder", "a flexible bag-like separator"], ["piston", "Piston", "a sliding rigid separator"]]) {
  add(`accumulator-${id}`, "valves", `Which accumulator separator in the supplied chart is ${clue}?`, [name, ...["Diaphragm", "Bladder", "Piston", "Filter screen"].filter(value => value !== name)], `The chart identifies ${name.toLowerCase()} separation between gas and hydraulic fluid. A ${id === "piston" ? "rigid moving piston differs from the flexible membrane and bag designs" : id === "diaphragm" ? "membrane differs from the bag-like bladder and sliding rigid piston" : "bag-like bladder differs from the membrane and rigid piston designs"}.`, [27, 28], [`The accumulator separator described as ${clue} is a _____.`, id]);
}

for (const [id, answer, prompt, why, word] of [
  ["pressure", "Pressure switch", "Which switch responds to hydraulic system pressure?", "The pressure switch provides a pressure-dependent indication. Temperature and actuator position are sensed by other switch types.", "pressure"],
  ["thermal", "Thermal switch", "Which switch indicates system overheating in the lesson?", "A thermal switch responds to temperature. Its overheating indication is different from low pressure or maximum actuator travel.", "thermal"],
  ["position", "Position switch", "Which switch indicates flap up, down or partial position?", "A position switch indicates where the mechanism is. The lesson separates actual position from pressure and overheating indications.", "position"],
  ["limit", "Limit switch", "Which switch type is associated with reaching a travel or pressure limit in the lesson?", "The source associates a limit switch with reaching a specified limit. That is distinct from simply identifying an intermediate flap position.", "limit"],
]) add(`switch-${id}`, "switches", prompt, [answer, ...["Pressure switch", "Thermal switch", "Position switch", "Limit switch"].filter(value => value !== answer)], why, [30, 31], [`Complete the named switch type for this function: ${prompt.replace(/^Which switch(?: type)? /, "").replace(/\?$/, "")} — _____ switch.`, word]);

add("fuse-purpose", "fuses", "Why is a hydraulic fuse fitted in a protected hydraulic branch?", ["To stop fluid loss after a downstream failure", "To store a reserve of pressurized fluid", "To clean all fluid passing through it", "To select the pilot's commanded actuator direction"], "A hydraulic fuse shuts off a failed downstream branch so the pump does not empty the system through the leak. It protects the remaining fluid supply rather than filtering contamination or storing energy.", [34], ["A hydraulic _____ isolates a failed branch to limit fluid loss.", "fuse"], [5, 7]);
add("pressure-fuse-sensing", "fuses", "What does the pressure fuse compare?", ["Pressure on its upstream and downstream sides", "Manufacture dates on two seals", "The electrical voltage at two switch contacts", "The colour of pressure and return lines"], "A downstream leak reduces pressure on that side. The resulting difference across the fuse produces the force that moves its piston toward closure.", [35, 36], ["A pressure fuse responds to a pressure _____ across its two sides.", "difference", ["differential", "imbalance"]], [5]);
add("pressure-fuse-close", "fuses", "A leak lowers downstream pressure in the illustrated pressure fuse. What moves it closed?", ["Higher upstream pressure acting against the lower downstream pressure", "An equal pressure on both sides plus no flow", "The selector handle rotating the fuse body", "The filter element changing its colour"], "The unbalanced hydraulic force moves the piston to close the passage. Equal pressure is the normal balanced condition described by the lesson, not the leak-closing trigger.", [35, 36], ["After a downstream leak, the pressure-fuse piston moves toward the _____ position.", "closed"], [5]);
add("pressure-fuse-normal", "fuses", "What holds the described pressure fuse open when pressure is balanced?", ["Its spring", "A filter cleaning handle", "The actuator's position light", "A fixed external drain"], "When the pressures balance, the spring maintains the open position in this design. This describes the illustrated operating principle, not a universal maintenance or reset instruction for every fuse.", [35, 36], ["With balanced pressures, the described pressure fuse is held open by a _____.", "spring"], [5]);
add("volume-fuse", "fuses", "What is measured by the volume-fuse mechanism in the component lesson?", ["The quantity of fluid passing through", "Only the reservoir's temperature", "The seal's manufacture quarter", "The actuator's electrical resistance"], "The volume fuse meters a small proportion of the passing fluid to move a piston. When the preset quantity has passed, the mechanism can shut off the branch; this differs from the pressure-comparison fuse.", [37, 38, 39, 40], ["A _____ fuse meters a preset quantity of passing hydraulic fluid.", "volume"], [7, 8]);
add("fuse-orifice", "fuses", "What part meters the small flow that moves the volume-fuse piston?", ["Metering orifice", "Accumulator bladder", "Filter cleaning blade", "Selector detent"], "A small metering orifice admits fluid to move the measuring piston. The measured piston movement allows the fuse to respond to passed volume rather than acting as an ordinary one-way check.", [37, 38], ["The volume fuse's small metering passage is an _____.", "orifice"], [8]);
add("fuse-orifice-size", "fuses", "In the described volume fuse, what effect does a smaller metering orifice have on piston movement?", ["Slower piston movement", "Faster piston movement", "It changes the fuse into a temperature switch", "It removes the need for any piston movement"], "A smaller orifice admits the metering flow more slowly, so the piston travels more slowly. This is a qualitative relationship from the mechanism, with no numerical flow calculation required.", [37], ["A smaller metering orifice makes the measuring piston move more _____.", "slowly", ["slow"]]);
add("volume-fuse-reverse", "fuses", "Which flow condition does the component deck show as a volume-fuse reset mechanism?", ["Reverse flow moving the internal parts back", "Changing only the external paint marking", "Increasing contamination in the filter", "Selecting a different seal colour"], "The illustrated reverse-flow condition moves the piston, sleeve and check parts back. The source also describes a spring reset; actual fuse designs and reset procedures differ, so normal flow alone must not be assumed to reset every fuse.", [37, 39, 40], ["One reset mechanism shown for the volume fuse uses _____ flow.", "reverse", ["reversed"]]);

add("sequence-role", "sequence", "Which valve arranges hydraulic events in a required order?", ["Sequence valve", "Shuttle valve", "Ordinary check valve", "Metering valve"], "A sequence or timing valve allows a later event after the earlier event reaches the required condition. In the landing-gear example, door and gear movements must occur in the intended order.", [41, 43, 44], ["The hydraulic timing valve is also called a _____ valve.", "sequence", ["sequencing"]], [9, 10]);
add("sequence-plunger", "sequence", "What operates the lesson's mechanically actuated sequence valve?", ["Another component pressing its plunger", "The filter's contamination colour", "The accumulator's manufacture date", "The O-ring's colour marking"], "Completion of another component's movement mechanically presses the plunger. That opens the controlled flow route for the next event, unlike the hydraulic-pressure actuation described for a priority valve.", [41, 42], ["A component finishing its movement presses the sequence valve's _____.", "plunger"], [9]);
add("sequence-check", "sequence", "What happens to the controlled reverse-flow path when the sequence-valve plunger is pressed?", ["It is opened for the next event", "It is permanently welded closed", "The fluid changes into compressed gas", "The accumulator's gas chamber opens to the fluid"], "The valve normally behaves as a check in one direction. Pressing its plunger allows the previously blocked direction, so the next part of the sequence can operate.", [41, 42], ["The sequence valve permits its controlled reverse flow when the plunger is _____.", "pressed", ["depressed"]], [9]);
add("gear-door-sequence", "sequence", "In the gear-retraction example, when is the gear-door closing step enabled?", ["After the gear reaches the required retracted position", "Before the gear is clear of the door opening", "Only after removing the hydraulic fluid", "Whenever the filter bypass opens"], "The gear movement operates the sequence valve to permit the door-closing step. This avoids commanding the doors closed before the gear is inside; the review's mixed extend/retract sentence is not used as an alternative sequence.", [41, 43, 44], ["After the gear retracts, the next enabled step is closing the gear _____.", "doors", ["door"]], [9, 10]);
add("priority-role", "sequence", "What does a priority valve do when system pressure becomes too low?", ["Restricts noncritical branches to preserve supply for critical functions", "Gives all available flow to noncritical branches first", "Replaces the accumulator separator", "Allows a failed line to drain the entire reservoir"], "A priority valve preserves supply to critical hydraulic functions by restricting noncritical branches below its setting. It allocates available pressure; it does not generate emergency pressure by itself.", [45], ["A _____ valve preserves hydraulic supply for critical functions when pressure is low.", "priority"], [11, 12, 13]);
add("priority-setting", "sequence", "What closing threshold is used in the review's priority-valve example?", ["2,200 psi", "1,500 psi", "3,000 psi", "1,000 psi"], "The review uses 2,200 psi as its example setting for restricting noncritical branches. This is a course example, not a universal pressure setting for every priority valve or aircraft.", [45], null, [11]);
add("priority-actuation", "sequence", "What actuates the priority valve, in contrast with the lesson's mechanically pressed sequence valve?", ["Hydraulic pressure", "The seal cure date", "A hand-operated filter cleaning blade", "The aircraft's cabin light switch"], "The review contrasts hydraulic-pressure actuation with the mechanical plunger of the sequence valve. Both relate operations, but the controlling input is different.", [41, 45], ["The review's priority valve is opened by _____ pressure.", "hydraulic"], [13]);

add("filter-purpose", "filters", "Why are filters installed in hydraulic systems?", ["To remove contamination from the fluid", "To store compressed gas for emergencies", "To select between two pressure supplies", "To change an actuator's commanded direction"], "Hydraulic components have close clearances that can be affected by contamination. Filters remove particles; this is distinct from pressure storage, selection and flow-direction control.", [47, 49], ["Hydraulic filters remove _____.", "contamination", ["contaminants", "particles"]], [14]);
add("filter-rating", "filters", "What does the lesson use to express a filter's particle-size rating?", ["Microns", "Volts", "Revolutions per minute", "Cure-date quarters"], "The filter rating describes the size of particles it removes, expressed in microns. A pressure rating describes a different property and must not be confused with filtration fineness.", [47], ["Hydraulic-filter particle sizes are expressed in _____.", "microns", ["micrometres", "micrometers"]], [14]);
add("filter-rating-example", "filters", "What common filter rating does the supplied review give as its example?", ["10 microns", "40 microns", "140 microns", "1,000 microns"], "The review gives 10 microns as a common rating in its example. It separately lists other element ratings and a visibility comparison, so this number must not be treated as the rating of every hydraulic filter.", [47, 51, 53, 54], null, [14]);
add("popout-indicator", "filters", "What does the review's red pop-out filter indicator warn about?", ["A pressure differential associated with a contaminated or restricted element", "A low accumulator gas charge only", "The selector being in neutral", "An incorrect colour marking on a new seal"], "Restriction produces a pressure difference across the element that can operate the indicator. The warning concerns filter condition; actual inspection, replacement and indicator-reset procedures govern the particular assembly.", [49, 50], ["The filter pop-out example responds to a pressure _____ across the element.", "differential", ["difference"]], [15, 17]);
add("filter-bypass", "filters", "Why can a hydraulic filter assembly include a bypass valve?", ["To maintain fluid supply when element restriction becomes excessive", "To guarantee that bypassed fluid is finely filtered", "To remove the need to service a contaminated element", "To convert hydraulic pressure into electrical power"], "A bypass maintains the required fluid supply around a restricted element, at the cost of that element's filtration. Bypass flow does not mean the contamination problem has been corrected.", [50, 52], ["The valve allowing flow around a restricted filter element is its _____ valve.", "bypass"], [15, 17]);
add("paper-pleats", "filters", "Why is the paper element folded into pleats?", ["To increase filtering surface area", "To reduce the available filtering area", "To store a gas precharge inside each fold", "To stop the return line from carrying any fluid"], "Pleats fit more filtering surface into the available space. The lesson links this area with efficient filtration and less resistance than a smaller effective surface.", [51, 52], ["The folds increasing a paper filter's surface area are called _____.", "pleats"], [18]);
add("paper-service", "filters", "How is the treated-paper element described in the lesson?", ["Low-cost and disposable", "A metal disc stack cleaned by turning a handle", "A woven stainless-steel mesh", "A porous block made by fusing metal powder"], "The paper element is an efficient, low-cost disposable element. The cleaning handle belongs to the Cuno disc design, while woven and sintered elements use different construction.", [51], ["The lesson describes treated-paper filter elements as low-cost and _____.", "disposable"], [18]);
add("paper-location", "filters", "Where does the lesson normally place its paper filter in a high-pressure system?", ["The return line", "The accumulator gas chamber", "The electrical supply line", "The reservoir vent outlet only"], "The lesson places this paper-filter example in the return line of a high-pressure system and notes pressure-side use in a low-pressure system. This is the described application, not approval to substitute an element in any assembly.", [51], ["In the high-pressure example, the paper filter is normally in the _____ line.", "return"], [18]);
add("steel-construction", "filters", "What provides the filtering surface in the stainless-steel filter example?", ["Finely woven wire mesh", "Pleated treated paper", "A stack of rotating discs and spacers", "A flexible rubber bladder"], "The fine weave of stainless-steel wire provides the filtration. The construction gives greater durability against pressure and collapse in the lesson's example; the actual element's rated fineness still applies.", [53], ["The stainless-steel element uses woven wire _____.", "mesh"], [19]);
add("two-stage-low", "filters", "How does the described two-stage filter route low flow?", ["Through both the primary and secondary elements", "Around both elements with no filtration", "Only into the accumulator gas chamber", "Out through an external drain"], "At low flow, the example sends fluid through both elements, including the very fine primary stage. That fine stage has useful filtration but would create excessive resistance if all high flow were forced through it.", [54, 56], ["At low flow, the two-stage example sends fluid through _____ elements.", "both", ["two", "2"]], [20]);
add("two-stage-high", "filters", "What happens to excess flow at high demand in the two-stage filter example?", ["It bypasses the fine primary element", "It bypasses every hydraulic component overboard", "It is sent into the gas side of the accumulator", "It closes the system's return line completely"], "Excess flow bypasses the fine primary stage while the secondary stage remains in the flow route. This limits the pressure drop associated with sending all high-demand flow through the finest element.", [55, 56], ["At high flow, excess fluid bypasses the fine _____ element.", "primary", ["first"]], [20]);
add("cuno-stack", "filters", "What forms the filtering stack in a Cuno filter?", ["Discs and spacers", "A single pleated paper sheet", "A flexible bladder and piston", "Only a felt shaft wiper"], "The Cuno design stacks discs and spacers to form filtering passages. Its structure and cleaning blade distinguish it from disposable paper and woven-wire elements.", [57, 58], ["A Cuno filter stacks discs and _____.", "spacers", ["spacer"]], [22]);
add("cuno-direction", "filters", "In which direction does fluid pass through the Cuno filter described in the lesson?", ["From outside toward the centre", "From the centre directly to an external drain", "From the gas chamber into the oil chamber", "From the electrical connector into the filter bowl"], "The illustrated fluid path is from the outside of the stack toward its centre. Contaminants collect where the cleaning arrangement can remove them from the discs.", [57], ["Fluid passes through the Cuno filter from outside toward the _____.", "centre", ["center"]], [22]);
add("cuno-cleaning", "filters", "What cleans between the discs when the Cuno filter handle is turned?", ["A cleaning blade", "A hydraulic accumulator bladder", "A spool-position switch", "An O-ring backup ring"], "A blade between the discs removes accumulated contamination as the disc stack is turned. The loosened material falls into the bowl for draining rather than disappearing from the assembly.", [57, 58], ["The Cuno filter's rotating discs are cleaned by a _____.", "blade", ["scraper"]], [22]);
add("cuno-bowl", "filters", "Where does loosened contamination collect in the Cuno filter example?", ["At the bottom of the bowl for draining", "Inside the accumulator gas chamber", "In the electrical selector contacts", "Permanently dissolved in the clean outlet fluid"], "The cleaning action moves contamination off the discs into the bottom of the bowl. The collection and draining step is separate from clearing the disc surfaces.", [57], ["Loosened Cuno-filter contamination collects at the bottom of the _____.", "bowl"], [22]);
add("sintered", "filters", "How is the porous metal of the sintered filter formed?", ["By fusing powdered metal under pressure", "By folding treated paper into pleats", "By weaving stainless-steel wire", "By stacking discs around cleaning blades"], "Sintering forms a porous metal structure from powder. The resulting pores provide the flow/filtering structure, which differs from woven wire and disc-stack construction.", [59, 60], ["A filter made from fused powdered metal is described as _____.", "sintered"]);

add("seal-purpose", "seals", "Which set describes the functions of seals in the supplied lesson?", ["Control leakage, exclude contamination and reduce wear", "Store pressure, select actuator direction and switch electrical power", "Filter particles, charge gas bottles and sense flap position", "Replace every valve, filter and reservoir"], "Seals limit internal/external leakage and contamination entry, helping protect components from wear. They do not replace the separate pressure-storage, direction-control and sensing components.", [61], ["The components limiting internal and external leakage are _____.", "seals", ["seal"]], [24]);
add("gasket", "seals", "Which seal category is used between surfaces with no relative movement?", ["Gasket", "Packing", "Shaft wiper", "Filter element"], "A gasket seals a stationary joint. Packing is the lesson's category for relative movement, so the motion of the two mating surfaces is the deciding distinction.", [61], ["A seal between stationary mating surfaces is a _____.", "gasket"], [24]);
add("packing", "seals", "Which seal category is used where the mating surfaces move relative to each other?", ["Packing", "Gasket", "Static crush washer only", "Filter bowl"], "Packing seals a moving interface, such as a piston moving inside an actuator. The moving contact distinguishes it from a stationary gasket joint.", [61], ["The lesson calls a seal at a moving interface _____.", "packing"], [24]);
add("seal-selection", "seals", "Why is one seal style unsuitable for every installation?", ["Pressure, fluid, surface clearances and motion differ", "Every system always uses identical fluid and pressure", "Only the external paint colour matters", "An O-ring part number has no relationship to its application"], "The lesson lists operating pressure, fluid type, surface finish/clearance and rotary or reciprocating motion as selection factors. Appearance alone does not establish suitability for a particular application.", [62], ["Besides pressure and clearances, seal selection must match the hydraulic _____ type.", "fluid"]);
add("one-way-chevron", "seals", "How is the Chevron or V-ring packing described in the review?", ["A one-way seal for pressure on one side", "A filter element for return-line contamination", "A pressure-storage chamber", "An electrical position sensor"], "Chevron (V-ring) packing has an open form arranged to respond to pressure from a particular side. This distinguishes its one-way sealing arrangement from the two-way O-ring example.", [63, 64, 65], ["Chevron packing is described as a _____-way seal.", "one", ["1"]], [25]);
add("chevron-orientation", "seals", "Which way should the open side of the V or U face in the lesson's one-way packing example?", ["Toward the pressure", "Away from the pressure", "Toward any convenient drain regardless of pressure", "Toward the shaft wiper regardless of pressure"], "Pressure acts into the open V or U and helps load its sealing lips. Reversing the packing would not provide the illustrated pressure-assisted sealing action.", [63, 64], ["The open side of the V or U faces the _____.", "pressure", ["highpressure"]], [25]);
add("opposed-chevron", "seals", "What arrangement is shown when pressure alternates from side to side across Chevron packing?", ["Two opposing sets of one-way packing", "One set facing away from all pressure", "A paper filter replacing the packing", "A shaft wiper without any pressure seal"], "Opposed sets provide a correctly facing one-way sealing arrangement for each pressure direction. The two sets serve different directions rather than duplicating a single-direction installation.", [64, 65], ["Alternating pressure requires Chevron sets facing in _____ directions.", "opposite", ["opposing"]], [25]);
add("ucup-use", "seals", "Which application is specifically listed for U-cup packing?", ["Brake assemblies and brake master cylinders", "Hydraulic-filter paper pleats", "Electrical switch contacts", "Gas-cylinder charging labels"], "The lesson identifies brake assemblies and master cylinders as U-cup applications. The U-shaped packing provides a pressure-sealing function there rather than acting as a filter or switch.", [63], ["The lesson lists U-cup packing in brake master _____.", "cylinders", ["cylinder"]]);
add("oring-two-way", "seals", "Which common seal is described as a two-way seal?", ["O-ring", "Single one-way Chevron set", "Filter bypass valve", "Felt shaft wiper"], "The O-ring can seal with pressure acting from either direction in the described arrangement. Correct material, groove fit and support still matter; two-way does not mean suitable for every installation.", [66, 67, 68], ["The common two-way seal in the lesson is an _____.", "O-ring", ["oring"]], [26]);
add("oring-roles", "seals", "How can an O-ring be used in the lesson?", ["As either a gasket or packing, according to the application", "Only as a filter element", "Only as an electrical insulator in switches", "Only as an unpressurized shaft wiper"], "An O-ring can seal a stationary joint as a gasket or a moving interface as packing. Its classification depends on the application rather than the ring shape alone.", [66], ["An O-ring at a moving interface functions as _____.", "packing"], [26]);
add("oring-squeeze", "seals", "Why is the O-ring given the specified squeeze in its groove?", ["To establish contact for a positive seal", "To keep the ring completely clear of both mating surfaces", "To turn it into a disposable paper filter", "To make its colour determine the fluid pressure"], "The groove and mating surface squeeze the ring into sealing contact. The installation diagram contrasts proper squeeze with a ring having no effective pinch and allowing leakage; actual groove dimensions must follow the approved design.", [66, 67, 68], ["The groove gives an O-ring the specified pinch or _____.", "squeeze", ["compression"]], [26]);
add("oring-chamfer", "installation", "Why does the installation lesson require a suitable chamfer at the cylinder edge?", ["To avoid cutting or damaging the ring during insertion", "To create an external leakage path", "To remove every need for ring squeeze", "To make fluid compatibility irrelevant"], "A sharp edge can nick or cut the ring as it is installed. The chamfer provides a suitable lead-in so installation does not destroy the sealing surface before the system is pressurized.", [69, 80, 83], ["The cylinder's suitable lead-in edge is a _____.", "chamfer"]);
add("oring-reuse", "installation", "What does the installation lesson say about reusing removed O-rings?", ["Do not reuse them", "Reuse any ring that still looks circular", "Reuse them after changing the colour marking", "Reuse them whenever a backup ring is fitted"], "The source explicitly says never to reuse O-rings. An apparently intact used ring is not established as serviceable for reinstallation merely by its shape or the presence of a backup ring.", [68], ["The lesson says removed O-rings must not be _____.", "reused"]);
add("backup-role", "seals", "What damage does a backup ring help prevent?", ["O-ring extrusion into the clearance between mating parts", "Filter-paper contamination", "Incorrect electrical switch polarity", "A gas bottle being charged through the wrong gauge"], "Pressure can force O-ring material into a clearance and damage it. A backup ring supports the O-ring at that gap; it is a support component rather than a substitute pressure seal selected solely by colour.", [70, 72, 74], ["Forcing O-ring material into a clearance is called _____.", "extrusion"], [27, 28]);
add("backup-position", "seals", "On which side of the O-ring does the lesson place a single backup ring for one-direction pressure?", ["The low-pressure side", "The high-pressure side only", "Inside the accumulator gas valve", "Outside the assembly without contact with the O-ring"], "The ring supports the low-pressure clearance into which the pressure would push the O-ring. This is the one-direction example; actual support for reversing pressure follows the specific design.", [70, 72, 74], ["For one-direction pressure, the backup ring supports the _____-pressure side.", "low"] , [28]);
add("backup-leather", "seals", "Which backup-ring material does the lesson associate with older systems?", ["Leather", "Pleated paper", "Carbon vane material", "Woven filter mesh"], "Leather is named as an older backup-ring material. The lesson distinguishes it from Teflon backup-ring forms and from materials used for filtering or pump vanes.", [71], ["The older backup-ring material named in the lesson is _____.", "leather"], [28]);
add("leather-face", "seals", "Which face of the leather backup ring is placed against the O-ring in the source example?", ["The smooth hair side", "The rough flesh side", "The side with loose fibres deliberately raised", "Either side without checking the stated arrangement"], "The source identifies the hair side as the smooth side placed against the ring. This is the particular leather-ring orientation in the lesson; handling still follows the applicable component instructions.", [71], ["In the leather backup-ring example, the _____ hair side faces the O-ring.", "smooth"], [28]);
add("backup-teflon", "seals", "Which material is named for the scarfed and spiral backup rings?", ["Teflon", "Felt", "Treated filter paper", "Carbon rotor material"], "The lesson identifies Teflon backup rings in scarfed and spiral forms. These are support-ring designs, distinct from felt wipers or filter elements.", [71, 73], ["The source names _____ as the material for its scarfed and spiral backup rings.", "Teflon", ["PTFE"]], [28]);
add("backup-scarf", "seals", "What requires attention when installing a scarfed backup ring?", ["Correct orientation of the scarf edge", "Matching the filter's pop-out colour", "Opening the accumulator gas chamber", "Removing the O-ring's required support"], "The scarfed joint must have the specified orientation. The source's wrong/correct diagrams show that the overlapping joint arrangement matters; merely having a split ring in the groove is insufficient.", [71, 73], ["Correct orientation matters at the backup ring's _____ edge.", "scarf", ["scarfed"]], [28]);
add("backup-inspection", "seals", "Which condition check is listed for backup rings?", ["Inspect for nicks, gouges and wear", "Confirm only that the package has a bright colour", "Stretch the ring until the joint opens permanently", "Ignore edge damage if the ring still fits the groove"], "Nicks, gouges and wear can compromise the ring's support at the seal clearance. A damaged edge is relevant to serviceability even when the ring can physically be placed in the groove.", [71], ["Backup-ring inspection includes checking for nicks, gouges and _____.", "wear"], [28]);

add("cure-date", "identification", "What does the seal's cure-date marking identify in the lesson?", ["Its manufacturing age information", "The hydraulic pressure currently in the system", "The actuator's travel direction", "The filter's particle rating"], "The source treats manufacturing or cure date as age information used when assessing a seal. It is not a pressure rating or proof that any particular fluid is compatible.", [75, 76, 77], ["The manufacturing-age marking is the seal's _____ date.", "cure"], [31]);
const quarters = [
  ["Q1", "January, February and March", "first", ["1", "Q1"]],
  ["Q2", "April, May and June", "second", ["2", "Q2"]],
  ["Q3", "July, August and September", "third", ["3", "Q3"]],
  ["Q4", "October, November and December", "fourth", ["4", "Q4"]],
];
for (const [code, months, word, aliases] of quarters) add(`quarter-${code.toLowerCase()}`, "identification", `Which months belong to ${code} in the source's seal cure-date code?`, [months, ...quarters.filter(row => row[0] !== code).map(row => row[1])], `${code} identifies the ${word} calendar quarter: ${months}. Reading the quarter code does not by itself establish an approved shelf life, and the impossible February 30 example is excluded.`, [77], [`${months} form the _____ calendar quarter.`, word, aliases], [31]);
add("cure-year", "identification", "How is the year represented in the review's cure-date code?", ["By its last two digits", "By the hydraulic-system pressure", "By the seal's colour only", "By the number of filter pleats"], "The code shows the year using its last two digits. The source notes that the digits alone can represent different centuries, so the complete package and approved life information are still needed.", [77, 78], ["The review's cure-date code uses the last two _____ of the year.", "digits"], [31]);
const colourRows = [
  ["blue", "Blue dot or stripe", "Air/oxygen or MIL-H-5606", "blue", ["Air/oxygen or MIL-H-5606", "Fuel", "Synthetic engine oil", "Skydrol hydraulic fluid"]],
  ["red", "Red dot or stripe", "Fuel", "red", ["Fuel", "Synthetic engine oil", "Petroleum-base engine oil or lubricant", "Skydrol hydraulic fluid"]],
  ["yellow", "Yellow dot", "Synthetic engine oil", "yellow", ["Synthetic engine oil", "Fuel", "Air/oxygen or MIL-H-5606", "Skydrol hydraulic fluid"]],
  ["white", "White stripe", "Petroleum-base engine oil or lubricant", "white", ["Petroleum-base engine oil or lubricant", "Synthetic engine oil", "Fuel", "Skydrol hydraulic fluid"]],
  ["green", "Green dash", "Skydrol hydraulic fluid", "green", ["Skydrol hydraulic fluid", "Fuel", "Synthetic engine oil", "Air/oxygen or MIL-H-5606"]],
  ["purple", "Purple dot", "Skydrol hydraulic fluid", "purple", ["Skydrol hydraulic fluid", "Fuel", "Synthetic engine oil", "Petroleum-base engine oil or lubricant"]],
];
for (const [id, marking, fluid, word, options] of colourRows) add(`colour-${id}`, "identification", `In the supplied O-ring colour chart, what does a ${marking.toLowerCase()} identify?`, options, `The supplied chart pairs ${marking.toLowerCase()} with ${fluid}. This tests the course chart, not permission to select or substitute a seal by colour alone. Confirm the approved part number, material and fluid compatibility.`, [68, 79], [`Complete this marking from the supplied chart: ${marking.replace(new RegExp(word, "i"), "_____")} = ${fluid}.`, word], [32], { term: `${marking} · ${fluid}` });
add("seal-part-number", "identification", "What source does the lesson require for selecting the correct seal part number?", ["The manufacturer's applicable parts catalogue", "Only the ring's apparent size and colour", "The last filter service entry", "The pressure-gauge face colour"], "The source directs the user to the applicable parts catalogue for the correct part number. Package, material and life information support selection; appearance alone does not verify the correct replacement.", [68, 76], ["For the correct seal part number, refer to the manufacturer's applicable parts _____.", "catalogue", ["catalog", "IPC"]]);
add("seal-package", "identification", "Which information does the lesson identify on an individually packaged seal?", ["Composition, manufacturer, cure date and part number", "Only the aircraft registration and tyre pressure", "Only the filter's bypass setting", "Only the last pilot's name"], "Packaging links the seal to its composition, manufacturing information and part number. Keeping that information associated with the seal helps prevent unverified selection based on shape alone.", [75, 76, 78], ["Alongside composition and cure date, the package identifies the seal's part _____.", "number"]);
add("installation-tools", "installation", "What tool-surface condition is required in the O-ring installation lesson?", ["Smooth and free of sharp edges", "Rough enough to grip the ring by cutting it", "Sharp enough to pierce the ring", "Unfinished, provided the handle is clean"], "Installation tools must avoid nicking or gouging the ring. The lesson gives polished brass as a possible tool material; the important surface feature is smoothness rather than a sharp picking edge.", [80, 81, 82, 83], ["O-ring installation tools should be polished _____.", "smooth"]);
add("wiper-role", "installation", "Why is a wiper fitted at an actuator shaft?", ["To remove dirt from the shaft and protect the seal", "To replace the pressure seal with an open gap", "To add dirt to the lubricating film", "To measure the seal's cure date"], "A lubricating film and moisture can attract dust. The wiper cleans the shaft before that contamination reaches the seal, helping prevent damage rather than serving as the main pressure-sealing element.", [84], ["The actuator component cleaning dirt from the shaft is a _____.", "wiper"], [33]);
add("wiper-material", "installation", "Which wiper material is named in the review?", ["Felt", "Pleated paper", "Carbon vanes", "Woven stainless-steel filter mesh"], "The lesson says shaft wipers are often made of felt. The material suits the wiping role described and should not be confused with a paper filter or pump-vane construction.", [84], ["The review says actuator wipers are often made of _____.", "felt"], [33]);
add("crush-washer", "installation", "How does the lesson's crush washer form a seal?", ["By deforming to fill the mating surface shape", "By staying perfectly rigid without surface contact", "By filtering contaminants through a fine mesh", "By storing gas pressure in a separate chamber"], "The soft washer deforms when crushed and conforms to the surfaces. This sealing mechanism is why the lesson identifies it as a one-time-use item rather than a reusable rigid spacer.", [85], ["A crush washer seals by _____ to the mating surfaces.", "deforming", ["conforming"]]);
add("crush-use", "installation", "What reuse rule does the source give for crush washers?", ["One-time use only", "Unlimited reuse if the paint remains intact", "Reuse whenever the washer is still circular", "Reuse after turning the washer over"], "Its sealing action uses permanent deformation of the soft material. The source therefore specifies one-time use instead of treating the used washer as an unchanged new sealing surface.", [85], ["A crush washer is a _____-use sealing item in the lesson.", "single", ["one", "onetime"]]);

add("pneumatic-medium", "pneumatics", "What working medium does the lesson identify for a pneumatic system?", ["Compressed gas such as air", "Only incompressible hydraulic oil", "Only electrical current", "A stack of dry metal filter discs"], "Pneumatic systems use compressed gas, while hydraulic systems use liquid. The source includes air systems and dry-nitrogen emergency examples; those applications do not make oxygen an interchangeable pressure source.", [87, 97], ["Pneumatic systems use compressed _____.", "gas", ["air"]]);
add("pneumatic-weight", "pneumatics", "Which feature does the source identify as a weight advantage of its pneumatic arrangement?", ["No hydraulic-style liquid return system is required", "No stored-energy hazard can exist", "Pressure bottles need no restraint", "Every component can be made without a pressure rating"], "The source links the light working medium and absence of a liquid return system with lower weight. This describes the arrangement's weight advantage and does not remove compressed-gas hazards.", [88], ["The source's weight-saving pneumatic arrangement avoids a liquid _____ system.", "return"]);
add("bottle-storage", "pneumatics", "Where is high-pressure gas normally stored in the lesson's bottle system?", ["Metal bottles", "Open hydraulic filter bowls", "Paper filter pleats", "Unsealed actuator drains"], "The high-pressure example stores gas in metal bottles, usually steel in the source. Storage and component ratings are specific to the installation; the bottle remains a stored-energy source after charging.", [89], ["The high-pressure gas-storage vessels in the lesson are metal _____.", "bottles", ["bottle", "cylinders"]]);
add("charging-valve", "pneumatics", "Which bottle valve is used for connecting the ground charging supply?", ["Charging valve", "Control shutoff valve", "Filter bypass valve", "Landing-gear sequence valve"], "The charging valve is the connection for replenishing the bottle from the charging equipment. The control valve instead retains or releases the stored gas for use.", [89, 90], ["The ground supply replenishes the bottle through its _____ valve.", "charging", ["charge"]]);
add("control-valve", "pneumatics", "Which bottle valve keeps the stored gas trapped until it is needed?", ["Control shutoff valve", "Charging connection only", "Filter pop-out indicator", "Shaft wiper"], "The control valve acts as the shutoff for stored gas. Keeping the charging and delivery/control functions separate explains why the bottle example has two valves.", [89, 90], ["The bottle's _____ valve acts as the shutoff retaining gas until needed.", "control", ["shutoff"]]);
add("bottle-only-limit", "pneumatics", "What limitation applies to the source's bottle-only system without an onboard compressor?", ["It cannot replenish its gas supply in flight", "It automatically produces an unlimited gas supply", "It never needs ground charging", "It eliminates the need for a shutoff valve"], "The bottle-only example depends on stored gas charged from the ground. The later compressor-equipped example can replenish in flight; the two descriptions concern different equipment configurations.", [89, 99], ["Without an onboard compressor, the bottle-only supply cannot be recharged in _____.", "flight"]);
add("compressor-recharge", "pneumatics", "What allows the later high-pressure example to recharge in flight?", ["An onboard high-pressure compressor", "Changing only the bottle colour", "Removing the charging valve", "Opening the actuator drain to atmosphere"], "The later arrangement has a high-pressure pump/compressor. That additional equipment explains its in-flight charging capability without making the earlier bottle-only limitation universal.", [99, 100], ["The equipment enabling in-flight replenishment is an onboard _____.", "compressor", ["pump"]]);
add("nitrogen-brakes", "pneumatics", "Which gas supplies the review's emergency brake backup example?", ["Nitrogen", "Oxygen", "Propane", "Acetylene"], "The review's emergency system supplies high-pressure nitrogen when the normal hydraulic brake supply fails. This is a specific system example and does not authorize substituting another gas or applying its pressure setting to another aircraft.", [91, 93, 94], ["The review's emergency brake gas is _____.", "nitrogen"], [36]);
add("brake-gas-removal", "pneumatics", "What does the review require before return to service after its nitrogen brake backup is used?", ["Bleed the nitrogen from the brakes using the applicable procedure", "Assume the introduced gas is hydraulic fluid", "Return to service without addressing the gas", "Change only the external handle marking"], "The review calls for the nitrogen to be bled from the brakes before return to service. The example distinguishes temporary emergency operation from restoring the normal hydraulic system, with actual work governed by the aircraft procedure.", [91, 93], ["The nitrogen introduced into the brake example must be _____ before return to service.", "bled", ["removed"]], [36]);
add("shuttle-sources", "pneumatics", "What does a shuttle valve allow in the review's arrangement?", ["Two alternative pressure sources supplying a common route", "Two incompatible fluids deliberately mixed in a gas chamber", "A fixed sequence based only on seal age", "Filtration through a stack of discs"], "A shuttle valve connects one available source to the outlet while isolating the other. This supports normal and emergency or ground pressure arrangements without simply joining both supplies together.", [94, 95, 96], ["The valve selecting between alternative pressure sources is a _____ valve.", "shuttle"], [37]);
add("shuttle-high-pressure", "pneumatics", "How does the higher pressure affect the illustrated shuttle valve?", ["It moves the shuttle to block the lower-pressure source", "It forces both sources to mix through the lower-pressure line", "It changes the valve into a filter", "It removes the outlet connection"], "The pressure difference shifts the shuttle, selecting the higher-pressure supply and blocking the other source. That separation prevents the selected pressure from simply flowing back into the lower-pressure supply.", [94, 95, 96], ["The higher-pressure supply shifts the shuttle to block the _____-pressure source.", "lower", ["low"]], [37]);
add("emergency-gear-selector", "pneumatics", "Why does the source's pneumatic gear-backup example first place the gear handle in GEAR DOWN?", ["To position the selector for displaced hydraulic fluid to return", "To filter nitrogen through the paper element", "To remove the need for a shuttle valve", "To close every return passage"], "The selected position establishes the return route for displaced fluid. The example then uses gas pressure to move the actuator; it is an explanation of that system, not a universal emergency gear-extension checklist.", [97, 98], ["The example selects GEAR DOWN to permit displaced hydraulic fluid to _____.", "return"]);
add("emergency-gear-gas", "pneumatics", "Which gas does the component lesson specify for its compressed-gas gear backup?", ["Dry nitrogen", "Oxygen", "Fuel vapour", "Carbon monoxide"], "The lesson specifically names dry nitrogen for the emergency example. The gas supply drives the actuator through the shuttle arrangement, and the approved installation determines gas and servicing requirements.", [97, 98], ["The illustrated gear backup uses dry _____.", "nitrogen"]);
add("actuator-gas-removal", "pneumatics", "What restoration requirement follows the source's pneumatic emergency gear operation?", ["Bleed gas from the actuator before return to service", "Treat the emergency gas as permanent hydraulic fluid", "Ignore the actuator once the gear is down", "Remove the fluid return path permanently"], "The source calls for introduced gas to be bled from the actuator before return to service. Temporary emergency actuation is not the same as restoring normal hydraulic serviceability.", [97, 98], ["After the example's emergency operation, gas must be bled from the _____.", "actuator"]);

add("compressor-first", "pumps", "What does the larger first-stage piston do in the two-stage compressor example?", ["Takes in air and gives it an initial compression", "Filters hydraulic oil through a paper element", "Seals the gas bottle permanently", "Meters the brake's hydraulic return fluid"], "The larger first stage takes in air and compresses it before delivery to the smaller stage. Dividing compression into stages differs from sending uncompressed air directly to final storage.", [99, 100], ["The larger compressor piston performs the _____ stage of compression.", "first", ["1"]]);
add("compressor-second", "pumps", "What does the smaller second-stage piston do?", ["Compresses the already compressed air to a higher pressure", "Expands the air directly overboard as a relief device", "Replaces the compressor's check valves", "Removes the need for an inlet passage"], "Air from the first stage is drawn into the smaller second stage and compressed further. This raises the pressure in stages rather than using the smaller piston to provide filtration.", [99, 100], ["After the larger piston, the smaller piston performs the _____ compression stage.", "second", ["2"]]);
add("compressor-checks", "pumps", "Why does the illustrated two-stage compressor use check valves?", ["To maintain the intended one-way air flow", "To select the seal cure quarter", "To mix the delivery line back into the inlet continuously", "To turn the compressor into a hydraulic accumulator"], "The check valves control the permitted flow direction through the compression stages. They support staged intake and delivery rather than allowing the pressure to drive air backward indiscriminately.", [99, 100], ["The compressor's _____ valves maintain one-way air flow.", "check"]);
add("low-pressure-instruments", "pumps", "Which application is identified for the low-pressure vane-pump system?", ["Gyroscopic instruments", "A high-pressure hydraulic filter bypass", "O-ring cure-date marking", "Cuno filter disc cleaning"], "The lesson describes vacuum drawing air through instruments and discharging pump air overboard. Drawing instrument air toward the pump helps avoid supplying the instruments with the pump's oil and dirt.", [101], ["The low-pressure system example supplies gyroscopic _____.", "instruments", ["gyros"]], [38]);
add("vane-drive", "pumps", "How are most low-pressure instrument pumps driven in the lesson?", ["By the engine", "By the hydraulic filter cleaning handle", "By the O-ring backup ring", "By the reservoir fluid-level pointer"], "The source identifies most of these pumps as engine-driven. That drive powers the rotating vane mechanism; the vacuum and pressure sides describe its air-flow functions rather than its power source.", [101], ["Most instrument vane pumps in the lesson are _____-driven.", "engine"], [38]);
add("vane-eccentric", "pumps", "Why is the vane-pump rotor mounted off centre?", ["To create chambers whose volume changes as the rotor turns", "To make every chamber remain exactly the same size", "To eliminate the need for inlet and outlet paths", "To turn the pump into a stationary gasket"], "The off-centre arrangement creates expanding and contracting chambers. Air enters the larger chamber and is pushed out as the chamber becomes smaller, producing the pumping action.", [102], ["The vane pump's off-centre rotor creates chambers of changing _____.", "volume", ["size"]]);
add("vane-flow", "pumps", "In the vane-pump explanation, when is air pushed toward the outlet?", ["As the chamber becomes smaller", "As the chamber expands without an outlet", "Only when the rotor stops completely", "When the seal package is opened"], "A contracting chamber reduces the space occupied by the trapped air and pushes it toward the outlet. The expanding chamber provides the intake part of the cycle.", [102], ["Air is discharged as a vane-pump chamber becomes _____.", "smaller"]);
add("wet-lubrication", "pumps", "How is the wet-type vane pump lubricated in the review?", ["By engine oil", "By carbon vanes requiring no oil", "By hydraulic-filter contamination", "By dry nitrogen alone"], "The wet pump uses engine oil for lubrication. This creates the need to separate oil from its discharged air, unlike the oil-free exhaust arrangement of the dry pump.", [103], ["The wet vane pump is lubricated by engine _____.", "oil"], [34]);
add("wet-separator", "pumps", "What extra device does the wet vane-pump example need in its discharge arrangement?", ["An oil separator", "A seal cure-date reader", "A Cuno cleaning blade", "A gear-door sequence plunger"], "The wet pump's engine-oil lubrication can put oil into the discharged air. The separator removes that oil from the air path; it is not a substitute for the pump's lubrication supply.", [103], ["The wet pump's discharge arrangement needs an oil _____.", "separator"], [34]);
add("wet-vanes", "pumps", "What vane material is specified for the wet pump in the review?", ["Metal", "Carbon", "Pleated paper", "Felt"], "The wet pump is described with metal vanes and a cast-iron body. The dry pump instead uses a carbon rotor and vanes, so material and lubrication distinguish the two examples.", [103], ["The wet-type vane-pump example uses _____ vanes.", "metal"], [34]);
add("wet-discharge", "pumps", "Which use is listed for the wet pump's discharged air?", ["De-icing boots", "O-ring cure-date identification", "Hydraulic-filter element manufacture", "Oil-reservoir part numbering"], "The source lists de-icing boots as a use of wet-pump discharge air. Its oil-separation requirement still applies; a use of discharge air is different from the pump's engine-oil lubrication source.", [103], ["The wet-pump discharge example supplies de-icing _____.", "boots", ["boot"]], [34]);
add("dry-material", "pumps", "What material is used for the dry pump's rotor and vanes?", ["Carbon", "Cast-iron vanes only", "Pleated paper", "Felt"], "The dry pump uses carbon for its rotor and vanes and requires no oil lubrication in the lesson. This differs from the wet pump's metal vanes and engine-oil lubrication.", [104], ["The dry vane pump uses a _____ rotor and vanes.", "carbon"], [35]);
add("dry-lubrication", "pumps", "What does the source say about lubrication of the dry vane pump?", ["It requires no oil lubrication", "It requires the same engine-oil feed as the wet example", "It is lubricated by hydraulic-filter debris", "It uses fuel as its normal lubricant"], "The dry carbon-vane arrangement does not use the wet pump's oil lubrication. The lesson links this with clean exhaust that may be used for instrument pressure applications.", [104], ["The carbon-vane pump requiring no oil lubrication is the _____ type.", "dry"], [35]);
add("dry-output", "pumps", "Which outputs may the dry pump provide in the source?", ["Vacuum or pressure", "Only hydraulic liquid return", "Only an electrical position signal", "Only filtered engine oil"], "The dry pump can provide vacuum and pressure service. Its clean exhaust can be useful for instruments, so dry construction does not restrict it to only one side of the pump's air-flow function.", [104], ["Besides vacuum, the dry pump may provide clean air _____.", "pressure"], [35]);
add("single-hand-pump", "pumps", "When does a single-action hand pump move fluid?", ["On one stroke", "On both strokes", "Only after two complete idle cycles", "Only while its piston remains motionless"], "The single-action design delivers on one stroke of the pumping cycle. The double-action design differs by moving fluid on both strokes rather than waiting for the same delivery direction each cycle.", [105], ["A hand pump delivering on one stroke is _____-action.", "single"]);
