function parts(bank, difficulty, kind, firstNumber = 1) {
  const count = Math.ceil(bank.length / 39), size = Math.floor(bank.length / count), extra = bank.length % count;
  let offset = 0;
  return Array.from({ length: count }, (_, index) => {
    const questions = bank.slice(offset, offset + size + Number(index < extra)); offset += questions.length;
    const suffix = `${kind === "typed" ? "one-word" : "practice"}-${firstNumber + index}`;
    const path = `${systemsModule2Path}/${suffix}`;
    return { slug: `systems-module2-${difficulty}-${index + 1}`, course: "Systems", courseSlug: "systems", basePath: systemsModule2Path, path, storageId: path, kind, difficulty, questions, number: index + 1, title: `${difficulty === "easy" ? "Review Practice" : difficulty === "medium" ? "Component Practice" : "One-Word Recall"} · Part ${index + 1}` };
  });
}
